import math

def discount_factor(rate,years,convention,periods=1):
    # Own bounded numeric interface;no curve selection/day-count implementation.
    if type(rate) is not float or not math.isfinite(rate) or not -0.2<=rate<=0.5:
        raise ValueError('invalid annual rate')
    if type(years) is not float or not math.isfinite(years) or not 0<=years<=50:
        raise ValueError('invalid year fraction')
    if type(convention) is not str or convention not in ('continuous','periodic'):
        raise ValueError('invalid convention')
    if type(periods) is not int or not 1<=periods<=12:
        raise ValueError('invalid periods per year')
    if convention=='continuous':
        if periods!=1:raise ValueError('periods unused;require sentinel1')
        return math.exp(-rate*years)
    return math.exp(-periods*years*math.log1p(rate/periods))

print(f'{discount_factor(0.1,1.0,"periodic"):.8f}')
print(f'{discount_factor(0.1,1.0,"continuous"):.8f}')
equivalent=math.log1p(0.1)
print(math.isclose(discount_factor(equivalent,1.0,'continuous'),discount_factor(0.1,1.0,'periodic'),rel_tol=1e-14))
print(f'{discount_factor(-0.05,1.0,"continuous"):.8f}')
print(discount_factor(0.1,0.0,'continuous'))
